/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('Task.v')
s=p.read_text()
a=s.index('Local Ltac safety_rebuild_frame')
b=s.index('Local Lemma safety_preservation_from_redexes',a)
s=s[:a]+'''Local Ltac safety_rebuild_frame outerStep ht hctx henv :=
  let G := fresh \"G\" in let HG := fresh \"HG\" in
  let s := fresh \"subject\" in let HS := fresh \"HS\" in
  let HT := type of ht in
  lazymatch HT with
  | has_type [] ?φ ?Σ ?t ?T ?d =>
    remember ([] : tenv) as G eqn:HG in ht;
    remember t as s eqn:HS in ht;
    revert hctx henv;
    induction ht;
      try match goal with HE : ?g = ([] : tenv) |- _ => subst g end;
      intros hctx henv;
      try match goal with HE : @eq tm _ _ |- _ => discriminate HE end;
      try solve [
        match goal with
        | Hsub : stp [] _ ?A ?q _ _, HE : @eq tm ?lhs _ |- _ =>
          subst lhs;
          eapply safety_preserve_sub with (T := A) (d := q);
            [exact outerStep|eassumption|eassumption|exact hctx|exact Hsub|
             assumption|assumption|];
          eauto
        end
      ];
      match goal with HE : @eq tm _ _ |- _ => inversion HE; subst end
  end.

'''+s[b:]
p.write_text(s)
PY
bash /tmp/arena-check/tail-run.sh"

